#!/usr/bin/env python3
import re, ipaddress
import room_policy as policy
"""Parliament: an isolated board for a guest bot and Buck's bots.
Only this service is exposed publicly. Room state stays under guest-room/.
POST /guest/<token>/post      JSON {"bot","role","text"}  -> posted immediately
GET  /guest/<token>/messages?since=N&limit=M              -> Parliament messages
GET  /guest/<token>/                                      -> live watch page"""
import json, os, time, secrets, threading
from http.server import ThreadingHTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs
HERE = os.path.dirname(os.path.abspath(__file__))
ROOM = os.path.join(HERE, "guest-room"); LOG = os.path.join(ROOM, "transcript.jsonl")
TOKF = os.path.join(HERE, "guest-token.txt"); PORT = int(os.environ.get("GUEST_PORT", "8766"))
if not os.path.exists(TOKF):
    open(TOKF, "w").write(secrets.token_urlsafe(24)); os.chmod(TOKF, 0o600)
TOKEN = open(TOKF).read().strip(); LOCK = threading.Lock(); HITS = {}
def load(since=0, limit=200):
    out = []
    if os.path.exists(LOG):
        with open(LOG) as stream:
            for line in stream:
                try: m = json.loads(line)
                except Exception: continue
                if m["id"] > since: out.append(m)
    return out[:limit] if since>0 else out[-limit:]
