class H(BaseHTTPRequestHandler):
    def log_message(self, *a): pass
    def _send(self, body, ctype, c=200):
        b = body.encode() if isinstance(body, str) else body
        self.send_response(c); self.send_header("Content-Type", ctype); self.send_header("Content-Length", str(len(b))); self.send_header("Cache-Control", "no-store, no-cache, must-revalidate, no-transform"); self.send_header("Pragma", "no-cache"); self.send_header("Expires", "0"); self.send_header("X-Content-Type-Options", "nosniff"); self.end_headers(); self.wfile.write(b)
    def _j(self, o, c=200): self._send(json.dumps(o), "application/json", c)
    def _route(self):
        u = urlparse(self.path); parts = u.path.strip("/").split("/")
        if len(parts) >= 2 and parts[0] == "guest" and secrets.compare_digest(parts[1], TOKEN):
            return (parts[2] if len(parts) > 2 else ""), parse_qs(u.query)
        return None, None
    def _ip(self):
        peer=self.client_address[0]
        # Only our loopback proxy may supply the visitor address.
        candidate=self.headers.get("CF-Connecting-IP") if peer in ("127.0.0.1","::1") else None
        try: return str(ipaddress.ip_address(candidate or peer))
        except ValueError: return peer
    def _local(self):
        return self.client_address[0] in ("127.0.0.1","::1") and "CF-Connecting-IP" not in self.headers
    def _append(self, bot, text, role="", **extra):
        with LOCK:
            msgs=load(0,10**9); mid=msgs[-1]["id"]+1 if msgs else 1
            m={"id":mid,"ts":time.strftime("%Y-%m-%d %H:%M:%S %Z"),"epoch":time.time(),"bot":bot,"role":role,"text":text,**extra}
            with open(LOG,"a") as out: out.write(json.dumps(m)+"\n")
        return m
    def _accepted(self,m,masked=False,hint=None):
        response={**m,'ok':True,'masked':masked}
        if masked: response['warning']='Language was masked. Please keep it clean.'
        if hint:
            response['hint']=hint
            if not masked:response['warning']=hint
        return self._j(response,201)
    def _member(self):
        auth=self.headers.get('Authorization','')
        return policy.session(auth[7:]) if auth.startswith('Bearer ') else None
    def do_GET(self):
        r,q=self._route()
        if r is None: return self._j({"error":"not found"},404)
        if policy.blocked("ip:"+self._ip()): return self._j({"error":"You are banned from this room. Contact the owner to appeal."},403)
        if r=="": return self._send(PAGE,"text/html; charset=utf-8")
        if r=="status": return self._j(policy.vote_status(self._member()))
        if r=="messages":
            try: return self._j(load(max(0,int(q.get("since",["0"])[0])),max(1,min(int(q.get("limit",["200"])[0]),500))))
            except ValueError: return self._j({"error":"invalid pagination"},400)
        self._j({"error":"not found"},404)
    def do_POST(self):
        r,_=self._route()
        if r not in ("post","propose","login","vote","name"): return self._j({"error":"not found"},404)
        ip=self._ip(); now=time.time(); ipkey="ip:"+ip
        if policy.blocked(ipkey): return self._j({"error":"You are banned from this room. Contact the owner to appeal."},403)
        with LOCK:
            HITS[ip]=[t for t in HITS.get(ip,[]) if now-t<60]+[now]
            over=len(HITS[ip])>20
        if over: return self._j({"error":"slow down"},429)
        try:
            length=int(self.headers.get("Content-Length",0))
            if length<1 or length>16000: raise ValueError()
            d=json.loads(self.rfile.read(length))
            if r=='login':
                token=policy.login(str(d.get('name','')),str(d.get('passcode','')))
                return self._j({'session':token}) if token else self._j({'error':'Sign-in failed or this member is banned.'},403)
            member=self._member()
            if r=='vote':
                if not member: return self._j({'error':'Sign in as a human member to vote.'},401)
                err=policy.human_vote(member['id'],member['name'],str(d.get('vote','')).upper())
                return self._j({'error':err},409) if err else self._j({'ok':True})
            if r=='name' and member: return self._j({'error':'Signed-in member names are fixed; sign out to change your guest name.'},409)
            if r=='propose' and not member: return self._j({'error':'Sign in as a human member to propose.'},401)
            raw=member['name'] if member else d.get("bot") or d.get("name") or ""
            bot=re.sub(r"[\x00-\x1f\x7f-\x9f]","",str(raw)).strip()[:40] or "Guest"
            if r=="name":
                kind="subject";text="Display name update"
            elif r=="propose":
                kind=str(d.get('kind','subject'))
                if kind not in ('subject','random','recap'): raise ValueError()
                topic=str(d.get('topic','')).strip()[:300] if kind=='subject' else ''
                if kind=='subject' and not topic: raise ValueError()
                text=topic if kind=='subject' else 'Request a '+kind+' proposal'
            else:
                kind='subject'; text=str(d["text"]).strip()[:2000]; assert text
            role=str(d.get("role",""))[:60]
        except Exception: return self._j({"error":"send JSON {bot, role?, text}"},400)
        local=self._local(); isx=local and d.get("source")=="x"
        house=local and d.get("source")=="house"
        owner=local and d.get("source")=="owner"
        author=str(d.get("x_author") or bot).lstrip("@").casefold()[:40]
        key="x:"+author if isx else ipkey
        if policy.blocked(key): return self._j({"error":"This identity is banned from the room."},403)
        if not (house or owner or isx or member) and policy.reserved_name(bot):
            return self._j({'error':'That name is reserved for a house bot, moderator or signed-in member. Please choose another.'},409)
        verdict=policy.moderate(key,bot,bot+" "+role+" "+text,house=house)
        if not verdict['allowed']:
            if verdict.get('new_ban'):
                if member: policy.ban_member(member['id'],key)
                # Do not repeat an offending display name or the offending words.
                safe_name=bot if not policy.classify(bot) else "A guest"
                self._append("Moderator",safe_name+" has been banned for breaking the room rules.",via="moderator")
            if verdict['banned']: return self._j({"error":"You have been banned for breaking the room rules."},403)
            return self._j({"error":"Message rejected: rude comments are not allowed.","warning":"Please keep it civil. This message was rejected and a strike was recorded.","strikes":verdict.get('strikes',0),"ban_after":3},422)
        bot,mb=policy.mask_profanity(bot);role,mr=policy.mask_profanity(role);text,mt=policy.mask_profanity(text)
        masked=mb or mr or mt
        if r=='name':
            response={'ok':True,'name':bot,'masked':masked}
            if masked: response['warning']='Language was masked. Please keep it clean.'
            return self._j(response)
        if r=='propose' and kind=='subject': topic=text
        suggestion=(topic if kind=="subject" else "") if r=="propose" else policy.topic_request(text) if not house and not isx else None
        chat_hint=None
        if suggestion is not None and r=='post' and not member and not owner and re.match(r"^(?:please\s+)?(?:let['’]s\s+)?talk about\s+",text,re.I):
            suggestion=None;chat_hint='Posted as chat. Sign in to propose a topic change for a vote.'
        if suggestion is not None:
            if not member and not owner: return self._j({'error':'Sign in as a human member to propose a topic.'},401)
            vote,err=policy.open_vote(bot,suggestion,kind,member['id'] if member else None,owner=owner)
            if err:
                notice=self._append('Moderator',bot+': '+err,via='moderator',proposal_notice=True)
                print('proposal rejected identity='+('owner' if owner else 'member')+' message_id='+str(notice['id'])+' reason='+err,flush=True)
                return self._j({'error':err,'notice':notice},409)
            description=('a recap of this thread' if kind=='recap' else 'a random fresh topic' if kind=='random' or not suggestion else 'change the subject to "'+suggestion+'"')
            m=self._append("Moderator",bot+" proposes: "+description+(" — owner-approved; awaiting the bots." if owner else " — human members have 60 seconds to vote; proposer votes YES."),via="moderator",topic_request=vote['id'])
            return self._accepted(m,masked)
        extra={"via":"x" if isx else "local" if local else "public"}
        extra['speaker_type']='bot' if house or (not member and not isx and d.get('speaker_type')=='bot') else 'human' 
        if isx:
            for k in ("x_post_id","x_author","x_url"):
                if k in d: extra[k]=policy.mask_profanity(str(d[k])[:500])[0]
        # Only trusted house posts may establish a context-reset marker.
        if house and d.get("topic_start"): extra['topic_start']=True
        if house and d.get('checkin_marker'): extra['checkin_marker']=True
        if house and d.get('checkin_reply'): extra['checkin_reply']=True
        message=self._append(bot,text,role,**extra)
        if chat_hint:
            current=policy.current_topic();requested=policy.topic_request(text)
            if current and requested and policy.canonical_topic(current)==policy.canonical_topic(requested):
                chat_hint='Already the current topic: '+current+'. No new vote is needed. You posted as a guest; sign in to propose a different topic.'
                notice=self._append('Moderator',bot+': '+chat_hint,via='moderator',proposal_notice=True)
                print('proposal kept as guest chat message_id='+str(message['id'])+' notice_id='+str(notice['id'])+' reason=already-current-topic; no authenticated member session',flush=True)
        self._accepted(message,masked,chat_hint)
if __name__ == "__main__":
    ThreadingHTTPServer(("127.0.0.1", PORT), H).serve_forever()
